import{_ as a,o as d,c as r,a4 as e}from"./chunks/framework.B-3VpRq4.js";const c=JSON.parse('{"title":"赛事资讯","description":"","frontmatter":{},"headers":[],"relativePath":"news/index.md","filePath":"news/index.md"}'),o={name:"news/index.md"};function i(l,t,h,s,n,b){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="赛事资讯" tabindex="-1">赛事资讯 <a class="header-anchor" href="#赛事资讯" aria-label="Permalink to &quot;赛事资讯&quot;">​</a></h1><blockquote><p>📰 追踪 RoboMaster 机甲大师赛最新动态</p></blockquote><hr><h2 id="🔥-rm2027-赛季规则变更前瞻" tabindex="-1">🔥 RM2027 赛季规则变更前瞻 <a class="header-anchor" href="#🔥-rm2027-赛季规则变更前瞻" aria-label="Permalink to &quot;🔥 RM2027 赛季规则变更前瞻&quot;">​</a></h2><p><em>根据 RMOC（RoboMaster Organizing Committee）发布的最新信息整理</em></p><h3 id="📋-变更概览" tabindex="-1">📋 变更概览 <a class="header-anchor" href="#📋-变更概览" aria-label="Permalink to &quot;📋 变更概览&quot;">​</a></h3><p>RM2027 赛季规则较 RM2026 赛季有以下重大调整：</p><hr><h2 id="🤖-地面兵种规则变更" tabindex="-1">🤖 地面兵种规则变更 <a class="header-anchor" href="#🤖-地面兵种规则变更" aria-label="Permalink to &quot;🤖 地面兵种规则变更&quot;">​</a></h2><h3 id="英雄机器人" tabindex="-1">英雄机器人 <a class="header-anchor" href="#英雄机器人" aria-label="Permalink to &quot;英雄机器人&quot;">​</a></h3><p>英雄机器人作为场上核心输出单位，42mm 弹丸机制迎来重大更新：</p><table tabindex="0"><thead><tr><th>项目</th><th>RM2026</th><th>RM2027 变更</th></tr></thead><tbody><tr><td>42mm 弹丸发射限制</td><td>原有机制</td><td>新增发射冷却与弹药管理</td></tr><tr><td>底盘功率</td><td>—</td><td>600W，速度上限 16.5m/s</td></tr><tr><td>枪口热量限制</td><td>—</td><td>新增热量管理系统</td></tr><tr><td>重量限制</td><td>—</td><td>6kg（42mm 发射机构含弹舱）</td></tr><tr><td>尺寸限制</td><td>—</td><td>400×400×400mm</td></tr><tr><td>电压限制</td><td>—</td><td>140V（42mm 发射机构专用）</td></tr><tr><td>底盘尺寸</td><td>—</td><td>600×600×600mm</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">关键变化</p><p>42mm 弹丸发射机构现在有独立的 <strong>热量限制</strong> 和 <strong>冷却机制</strong>。需要重新设计发射策略！</p></div><h3 id="步兵机器人" tabindex="-1">步兵机器人 <a class="header-anchor" href="#步兵机器人" aria-label="Permalink to &quot;步兵机器人&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项目</th><th>RM2026</th><th>RM2027 变更</th></tr></thead><tbody><tr><td>数量</td><td>2 台</td><td>2 台（不变）</td></tr><tr><td>17mm 弹丸</td><td>标准配置</td><td>标准配置</td></tr><tr><td>功率</td><td>原有值</td><td>底盘 300W</td></tr></tbody></table><h3 id="工程机器人" tabindex="-1">工程机器人 <a class="header-anchor" href="#工程机器人" aria-label="Permalink to &quot;工程机器人&quot;">​</a></h3><p>工程机器人在 RM2027 赛季中的定位更加明确：</p><ul><li>救援能力要求提升</li><li>经济系统交互规则调整</li></ul><h3 id="哨兵机器人" tabindex="-1">哨兵机器人 <a class="header-anchor" href="#哨兵机器人" aria-label="Permalink to &quot;哨兵机器人&quot;">​</a></h3><p>哨兵机器人的自动化和通信能力有新要求：</p><ul><li><strong>通信协议</strong>：UDP + MQTT（ProtoBuf 编码）</li><li><strong>网口要求</strong>：RJ45 千兆 (1GbE)</li><li><strong>UI 显示</strong>：裁判系统信息展示要求提升</li><li>支持自定义数据交互（/ 图形化界面）</li></ul><hr><h2 id="🪁-空中兵种规则变更" tabindex="-1">🪁 空中兵种规则变更 <a class="header-anchor" href="#🪁-空中兵种规则变更" aria-label="Permalink to &quot;🪁 空中兵种规则变更&quot;">​</a></h2><h3 id="无人机" tabindex="-1">无人机 <a class="header-anchor" href="#无人机" aria-label="Permalink to &quot;无人机&quot;">​</a></h3><p>无人机细则更新：</p><ul><li>电池容量限制：300Wh</li><li>电压限制：30V</li><li>起飞重量公式：$$y = 0.001225x + 0.3225$$（其中 $$y \\in [0.15, 0.249]$$）</li><li>尺寸限制根据重量动态计算</li></ul><hr><h2 id="⚖️-赛制与判罚调整" tabindex="-1">⚖️ 赛制与判罚调整 <a class="header-anchor" href="#⚖️-赛制与判罚调整" aria-label="Permalink to &quot;⚖️ 赛制与判罚调整&quot;">​</a></h2><h3 id="赛制变化" tabindex="-1">赛制变化 <a class="header-anchor" href="#赛制变化" aria-label="Permalink to &quot;赛制变化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>调整项</th><th>说明</th></tr></thead><tbody><tr><td>经济系统</td><td>经济获取机制调整，新增多种经济来源</td></tr><tr><td>补血机制</td><td>补血点规则优化，恢复速度调整</td></tr><tr><td>伤害判定</td><td>伤害计算公式调整</td></tr></tbody></table><h3 id="判罚变化" tabindex="-1">判罚变化 <a class="header-anchor" href="#判罚变化" aria-label="Permalink to &quot;判罚变化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>判罚项</th><th>RM2027 更新</th></tr></thead><tbody><tr><td>冲撞判罚</td><td>力度阈值降低 25%，判罚更严格</td></tr><tr><td>违规停留</td><td>持续时间缩短至 30 秒</td></tr><tr><td>场地违规</td><td>新增禁区判定，停留超 1.5 秒即判罚，缓冲期 120 秒</td></tr></tbody></table><h3 id="场地更新" tabindex="-1">场地更新 <a class="header-anchor" href="#场地更新" aria-label="Permalink to &quot;场地更新&quot;">​</a></h3><ul><li>场地元素新增/调整</li><li>部分障碍物尺寸变化（120cm × 75cm 尺寸的元素）</li><li>通信接口统一为 RJ45 千兆网口</li></ul><hr><h2 id="📅-赛季时间线" tabindex="-1">📅 赛季时间线 <a class="header-anchor" href="#📅-赛季时间线" aria-label="Permalink to &quot;📅 赛季时间线&quot;">​</a></h2><div class="timeline"><div class="timeline-item"><strong>2026 年 9-11 月</strong><p>RM2027 赛季报名启动、规则手册发布</p></div><div class="timeline-item"><strong>2027 年 3-5 月</strong><p>高校联盟赛 (RMUL) 区域赛</p></div><div class="timeline-item"><strong>2027 年 5-6 月</strong><p>超级对抗赛 (RMUC) 区域赛</p></div><div class="timeline-item"><strong>2027 年 7-8 月</strong><p>全国赛 / 复活赛 / 总决赛</p></div></div><hr><h2 id="🔗-官方资讯渠道" tabindex="-1">🔗 官方资讯渠道 <a class="header-anchor" href="#🔗-官方资讯渠道" aria-label="Permalink to &quot;🔗 官方资讯渠道&quot;">​</a></h2><table tabindex="0"><thead><tr><th>渠道</th><th>链接</th><th>说明</th></tr></thead><tbody><tr><td>官网</td><td><a href="https://www.robomaster.com/" target="_blank" rel="noreferrer">robomaster.com</a></td><td>赛事官方入口</td></tr><tr><td>论坛</td><td><a href="https://bbs.robomaster.com/" target="_blank" rel="noreferrer">bbs.robomaster.com</a></td><td>规则 FAQ、开源分享、战队交流</td></tr><tr><td>规则参考</td><td><a href="https://bbs.robomaster.com/article/4820" target="_blank" rel="noreferrer">bbs.robomaster.com/article/4820</a></td><td>官方规则帖</td></tr><tr><td>公众号</td><td>RoboMaster 机甲大师</td><td>微信搜索关注</td></tr><tr><td>B站</td><td><a href="https://space.bilibili.com/31976414" target="_blank" rel="noreferrer">RoboMaster 官方</a></td><td>比赛直播、精彩集锦</td></tr><tr><td>GitHub</td><td><a href="https://github.com/robomaster-oss" target="_blank" rel="noreferrer">RoboMaster OSS</a></td><td>官方开源项目</td></tr></tbody></table><hr><h2 id="机器人兵种一览" tabindex="-1">机器人兵种一览 <a class="header-anchor" href="#机器人兵种一览" aria-label="Permalink to &quot;机器人兵种一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>兵种</th><th>数量</th><th>功能</th></tr></thead><tbody><tr><td>英雄机器人</td><td>1 台</td><td>主力输出，发射 42mm 弹丸</td></tr><tr><td>工程机器人</td><td>1 台</td><td>救援、获取矿石、经济交互</td></tr><tr><td>步兵机器人</td><td>2 台</td><td>灵活输出，发射 17mm 弹丸</td></tr><tr><td>哨兵机器人</td><td>1 台</td><td>全自动防御，UDP + MQTT 通信</td></tr><tr><td>无人机</td><td>1 台</td><td>空中火力支援</td></tr></tbody></table><hr><div class="tip custom-block"><p class="custom-block-title">提示</p><p>本页面内容基于 RMOC 官方发布信息整理，具体规则以官方最终版规则手册为准。我们会持续更新。</p></div>',45)])])}const u=a(o,[["render",i]]);export{c as __pageData,u as default};
